        CompoundTag stateData = NbtUtils.writeBlockState(state);
        nbt.put("block", stateData);

        if(tile != null)
        {
            CompoundTag tileData = tile.saveWithId(tile.getLevel().registryAccess());
            nbt.put("tile", tileData);
        }
    }

